import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import type { Municipio } from '../models/municipio.model';
import {
  Solicitud,
  SolicitudQueryParams,
  SolicitudExportParams,
  PaginatedSolicitudes,
} from '../models/solicitud.model';
import { statusToClass } from '../models/solicitud-status.util';
import { environment } from '../../../environments/environment';
export type { Municipio };

type RawSolicitud = Omit<Solicitud, 'statusClass'>;

interface SingleSolicitudResponse {
  data: RawSolicitud;
}

export interface SolicitudResponse {
  data: {
    id: number;
    folio: string;
    status: string;
    personalidad_juridica: string;
    created_at: string;
    documentos: { clave: string; documento_id: number }[];
  };
  message: string;
}

export interface DocumentoItemState {
  file: File | null;
  id: number | null;
}

export interface DocumentoParaFirma {
  clave: string;
  nombreOriginal: string;
}

export interface SolicitudFormValue {
  rfc: string;
  correoElectronico: string;
  confirmarCorreo: string;
  nombreCompleto?: string;
  tieneRepresentanteLegal?: boolean;
  denominacionRazonSocial?: string;
  numeroFolio?: string;
  fechaOtorgamiento?: string;
  nombreRepresentante?: string;
  primerApellidoRepresentante?: string;
  segundoApellidoRepresentante?: string;
}

export interface SolicitudDocumentoPayload {
  clave: string;
  documento_id: number;
  firma_serial?: string;
}

export interface SolicitudPayload {
  personalidad_juridica: 'fisica' | 'moral';
  rfc: string;
  correo_electronico: string;
  status: string;
  nombre_proyecto: string | null;
  municipio_id?: number | null;
  documentos: SolicitudDocumentoPayload[];
  nombre_completo?: string;
  tiene_representante_legal?: boolean;
  denominacion_razon_social?: string;
  numero_folio?: string;
  fecha_otorgamiento?: string;
  nombre_representante?: string;
  primer_apellido_representante?: string;
  segundo_apellido_representante?: string | null;
}

@Injectable({ providedIn: 'root' })
export class SolicitudService {
  private readonly http = inject(HttpClient);

  getMunicipios(): Observable<Municipio[]> {
    return this.http.get<{ data: Municipio[] }>(`${environment.apiUrl}/municipios`).pipe(
      map(res => res.data),
    );
  }

  enviarSolicitud(
    personalidad: 'fisica' | 'moral',
    formValue: SolicitudFormValue,
    nombreProyecto: string | null,
    documentosMap: Record<string, DocumentoItemState>,
    allowedClaves: string[],
    firmaSerialMap?: Record<string, string>,
    municipioId?: number | null,
  ): Observable<{ id: number; folio: string; documentos: DocumentoParaFirma[] }> {
    if (formValue.correoElectronico !== formValue.confirmarCorreo) {
      throw new Error('Los correos electrónicos no coinciden.');
    }

    const documentos = allowedClaves
      .map(clave => {
        const docId = documentosMap[clave]?.id;
        if (docId === null || docId === undefined) return null;
        const payload: SolicitudDocumentoPayload = { clave, documento_id: docId };
        if (firmaSerialMap?.[clave]) {
          payload.firma_serial = firmaSerialMap[clave];
        }
        return payload;
      })
      .filter((doc): doc is SolicitudDocumentoPayload => doc !== null);

    const documentosParaFirma: DocumentoParaFirma[] = allowedClaves
      .map(clave => ({
        clave,
        nombreOriginal: documentosMap[clave]?.file?.name ?? clave,
      }))
      .filter(doc => documentosMap[doc.clave]?.id !== null && documentosMap[doc.clave]?.id !== undefined);

    const payload: SolicitudPayload = {
      personalidad_juridica: personalidad,
      rfc: formValue.rfc,
      correo_electronico: formValue.correoElectronico,
      status: 'Enviada',
      nombre_proyecto: nombreProyecto,
      municipio_id: municipioId ?? null,
      documentos
    };

    if (personalidad === 'moral') {
      payload['denominacion_razon_social'] = formValue.denominacionRazonSocial;
      payload['numero_folio'] = formValue.numeroFolio;
      payload['fecha_otorgamiento'] = formValue.fechaOtorgamiento;
      payload['nombre_representante'] = formValue.nombreRepresentante;
      payload['primer_apellido_representante'] = formValue.primerApellidoRepresentante;
      payload['segundo_apellido_representante'] = formValue.segundoApellidoRepresentante || null;
    } else {
      payload['nombre_completo'] = formValue.nombreCompleto;
      payload['tiene_representante_legal'] = formValue.tieneRepresentanteLegal;
    }

    return this.createSolicitud(payload, documentosParaFirma);
  }

  generarPdfSolicitud(
    personalidad: 'fisica' | 'moral',
    formValue: SolicitudFormValue,
    nombreProyecto: string,
    municipioId: number,
    documentosList: { clave: string; documento_id?: number | null; nombre?: string }[] = [],
  ): Observable<ArrayBuffer> {
    const payload: Record<string, unknown> = {
      personalidad_juridica: personalidad,
      rfc: formValue.rfc,
      correo_electronico: formValue.correoElectronico,
      nombre_proyecto: nombreProyecto,
      municipio_id: municipioId,
      documentos: documentosList,
    };

    if (personalidad === 'moral') {
      payload['denominacion_razon_social'] = formValue.denominacionRazonSocial;
      payload['numero_folio'] = formValue.numeroFolio;
      payload['fecha_otorgamiento'] = formValue.fechaOtorgamiento;
      payload['nombre_representante'] = formValue.nombreRepresentante;
      payload['primer_apellido_representante'] = formValue.primerApellidoRepresentante;
      payload['segundo_apellido_representante'] = formValue.segundoApellidoRepresentante || null;
    } else {
      payload['nombre_completo'] = formValue.nombreCompleto;
      payload['tiene_representante_legal'] = formValue.tieneRepresentanteLegal;
    }

    return this.http.post(`${environment.apiUrl}/solicitudes/generar-pdf`, payload, {
      responseType: 'arraybuffer',
    });
  }

  createSolicitud(
    payload: SolicitudPayload,
    documentosParaFirma: DocumentoParaFirma[] = []
  ): Observable<{ id: number; folio: string; documentos: DocumentoParaFirma[] }> {
    return this.http.post<SolicitudResponse>(`${environment.apiUrl}/solicitudes`, payload).pipe(
      map(res => ({
        id: res.data.id,
        folio: res.data.folio,
        documentos: documentosParaFirma,
      })),
    );
  }

  getByFolio(folio: string): Observable<Solicitud> {
    return this.http
      .get<SingleSolicitudResponse>(`${environment.apiUrl}/solicitudes/${folio}`)
      .pipe(
        map(response => {
          const item = response.data;
          return {
            ...item,
            id: item.id,
            createdAt: item.createdAt,
            fechaSesion: item.fechaSesion || '—',
            fechaResolucion: item.fechaResolucion || '—',
            documentos: item.documentos ?? [],
            statusClass: statusToClass(item.status),
          };
        }),
      );
  }

  actualizarSolicitud(folio: string, campos: Record<string, unknown>): Observable<Solicitud> {
    return this.http
      .patch<SolicitudResponse>(`${environment.apiUrl}/solicitudes/${folio}`, campos)
      .pipe(
        map(res => res.data as unknown as Solicitud),
      );
  }

  getSolicitudes(params: SolicitudQueryParams): Observable<PaginatedSolicitudes> {
    const httpParams = new HttpParams()
      .set('page', params.page)
      .set('per_page', params.perPage);

    const filtered = this.applyFilterParams(httpParams, params);

    return this.http
      .get<{ data: RawSolicitud[]; meta: { current_page: number; last_page: number; per_page: number; total: number; from: number; to: number } }>(
        `${environment.apiUrl}/solicitudes`,
        { params: filtered },
      )
      .pipe(
        map(response => ({
          ...response.meta,
          data: response.data.map(item => ({
            ...item,
            fechaSesion: item.fechaSesion || '—',
            fechaResolucion: item.fechaResolucion || '—',
            statusClass: statusToClass(item.status),
          })),
        })),
      );
  }

  getSolicitudesForExport(params: SolicitudExportParams): Observable<{ data: Solicitud[] }> {
    const httpParams = this.applyFilterParams(new HttpParams(), params);

    return this.http
      .get<{ data: RawSolicitud[] }>(`${environment.apiUrl}/solicitudes/export`, { params: httpParams })
      .pipe(
        map(response => ({
          data: response.data.map(item => ({
            ...item,
            fechaSesion: item.fechaSesion || '—',
            fechaResolucion: item.fechaResolucion || '—',
            statusClass: statusToClass(item.status),
          })),
        })),
      );
  }

  private applyFilterParams(
    httpParams: HttpParams,
    filters: SolicitudQueryParams | SolicitudExportParams,
  ): HttpParams {
    let params = httpParams;
    if (filters.search) params = params.set('search', filters.search);
    if (filters.status) {
      const statusValue = Array.isArray(filters.status) ? filters.status.join(',') : filters.status;
      params = params.set('status', statusValue);
    }
    if (filters.dateFrom) params = params.set('date_from', filters.dateFrom);
    if (filters.dateTo) params = params.set('date_to', filters.dateTo);
    if (filters.conMetricas) params = params.set('con_metricas', '1');
    return params;
  }
}
